update_rule.pseudocode:
for each day t:
  # Decay
  for each edge e in G:
    if rand() < contact_decay_prob: remove e
  # Rewiring
  edges_to_rewire = floor(daily_rewiring_rate * |E|)
  repeat edges_to_rewire times:
    pick node u proportional to degree
    if rand() < triadic_closure_prob:
      pick neighbor v of u, then neighbor w of v not connected to u; add edge (u,w) if not exists
    else:
      pick candidate w not equal u; acceptance prob = homophily_strength if group(w)==group(u) else (1 - homophily_strength)
      if rand() < acceptance_prob and edge (u,w) not exists: add edge (u,w)
  # Keep average degree stable by adding edges if |E| decreased too much
  compute stats (mean_degree, clustering, assortativity) for reporting

for each day t:
  base = baseline_media_intensity
  shock = media_shock_magnitude if t == media_shock_day else 0
  for each person i:
    media_intensity[i] = (base + shock) * (1 if media_subscribed[i] else 0.5)
  # Policy
  if t >= policy_start_day:
    for each person i:
      eligible[i] = (rand() < eligibility_rate)
      incentive = subsidy_effect_weight * subsidy_amount
      penalty = enforcement_prob * fine_amount
      policy_effect[i] = incentive + penalty if eligible[i] else penalty
  else:
    eligible[:] = False; policy_effect[:] = 0

for each day t:
  adoption_rate = mean( state == Adopted )
  new_adopters = count(events.new_adopters at t)
  cumulative_adopters = previous_cumulative + new_adopters - backsliders_today
  mean_degree = 2 * |E| / |V|
  if report_groups:
    group_rates = {g: mean(state[g]==Adopted) for each group g}
  # smoothing for reporting only
  report_adoption_rate = moving_average(adoption_rate, window=smoothing_window_days)
  emit all observables
